#include "wsoundmask89.h"
static wsound89_i16 sat(wsound89_i32 v){if(v>32767)return 32767;if(v<-32768)return -32768;return(wsound89_i16)v;}
wsound89_result wsoundmask89_init(wsoundmask89_context*c){if(!c)return WSOUND89_EINVAL;c->mask_env=0;c->detail_gain_q15=32767;c->threshold_q15=7000;return WSOUND89_OK;}void wsoundmask89_trigger(wsoundmask89_context*c,wsound89_u16 level){if(c&&level>c->mask_env)c->mask_env=level;}
wsoundmask89_quality wsoundmask89_decide(const wsoundmask89_context*c,wsound89_u16 level,wsound89_u16 priority){wsound89_i32 score;if(!c)return WSOUNDMASK89_FULL;score=(wsound89_i32)level+priority-(c->mask_env>>1);if(score<(wsound89_i32)c->threshold_q15)return WSOUNDMASK89_VIRTUAL;if(score<(wsound89_i32)c->threshold_q15*2)return WSOUNDMASK89_REDUCED;return WSOUNDMASK89_FULL;}
wsound89_i16 wsoundmask89_mix_sample(wsoundmask89_context*c,wsound89_i16 main,wsound89_i16 detail){wsound89_i32 target,out;if(!c)return sat((wsound89_i32)main+detail);target=32767-c->mask_env;if(target<5000)target=5000;c->detail_gain_q15+=(target-c->detail_gain_q15)>>6;out=(wsound89_i32)main+(((wsound89_i32)detail*c->detail_gain_q15)>>15);c->mask_env=(c->mask_env*32690)>>15;return sat(out);}
